import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const POLL_MS = 150;

const db = openDatabase();
let stopping = false;
const stopController = new AbortController();

const beat = db.prepare(`
  INSERT INTO heartbeat (name, beat_at) VALUES ('worker', ?)
  ON CONFLICT(name) DO UPDATE SET beat_at = excluded.beat_at
`);
function heartbeat(): void {
  try {
    beat.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}

// Any job left 'running' belongs to a worker that died mid-attempt. The interrupted attempt
// did not finish, so it is not counted: requeue it to run again as the same attempt number.
const now = () => new Date().toISOString();
db.prepare(`
  UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0,
                  run_after = 0, updated_at = ?
  WHERE status = 'running'
`).run(now());

const claim = db.prepare(`
  UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
  WHERE id = (SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1)
    AND status = 'queued'
  RETURNING *
`);
const setProgress = db.prepare(`
  UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'
`);
const complete = db.prepare(`
  UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ?
  WHERE id = ? AND status = 'running'
`);
const requeue = db.prepare(`
  UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ?
  WHERE id = ? AND status = 'running'
`);
const fail = db.prepare(`
  UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = ?, updated_at = ?
  WHERE id = ? AND status = 'running'
`);
const abandon = db.prepare(`
  UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0,
                  run_after = 0, updated_at = ?
  WHERE id = ? AND status = 'running'
`);

async function wait(ms: number): Promise<boolean> {
  try {
    await sleep(ms, undefined, { signal: stopController.signal });
    return true;
  } catch {
    return false;
  }
}

async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  if (attempt <= job.fail_attempts) {
    // Fails at its first step, before any progress.
    if (!(await wait(STEP_MS))) return void abandon.run(now(), job.id);
    if (attempt >= MAX_ATTEMPTS) {
      fail.run('transient failure', now(), job.id);
    } else {
      requeue.run(Date.now() + RETRY_DELAY_MS, now(), job.id);
    }
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    if (!(await wait(STEP_MS))) return void abandon.run(now(), job.id);
    if (step < job.steps) setProgress.run(step, now(), job.id);
  }
  complete.run(job.input.toUpperCase(), now(), job.id);
}

function shutdown(): void {
  if (stopping) return;
  stopping = true;
  stopController.abort();
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

heartbeat();
const hbTimer = setInterval(heartbeat, 1000);
console.log('worker started');

while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claim.get(now(), Date.now()) as JobRow | undefined;
  } catch (err) {
    console.error('claim failed', err);
  }
  if (job) {
    try {
      await processJob(job);
    } catch (err) {
      console.error('processing failed', err);
      try {
        abandon.run(now(), job.id);
      } catch {
        /* ignore */
      }
      await wait(POLL_MS);
    }
  } else {
    await wait(POLL_MS);
  }
}

clearInterval(hbTimer);
try {
  db.prepare("DELETE FROM heartbeat WHERE name = 'worker'").run();
  db.close();
} catch {
  /* ignore */
}
process.exit(0);

