process.on('SIGTERM', shutdown);

heartbeat();
const hbTimer = setInterval(heartbeat, 1000);
console.log('worker started');

while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claim.get(now(), Date.now()) as JobRow | undefined;
  } catch (err) {
    console.error('claim failed', err);
  }
  if (job) {
    try {
      await processJob(job);
    } catch (err) {
      console.error('processing failed', err);
      try {
        abandon.run(now(), job.id);
      } catch {
        /* ignore */
      }
      await wait(POLL_MS);
    }
  } else {
    await wait(POLL_MS);
  }
}

clearInterval(hbTimer);
try {
  db.prepare("DELETE FROM heartbeat WHERE name = 'worker'").run();
  db.close();
} catch {
  /* ignore */
}
process.exit(0);

